(6973696, 1052632, 124982, '<td valign="top">Nice, gritty image. Almost like she''s flying a kite in a sandstorm!! Fairly certain this image will garner one or more of the alternative awards (posthumous, spurgeon etc)</td>', 'Nice, gritty image. Almost like she''s flying a kite in a sandstorm!! Fairly certain this image will garner one or more of the alternative awards (posthumous, spurgeon etc)', '2013-02-06 18:39:33.000000', NULL, 1),
(6973702, 1052363, 124982, '<td valign="top">I absolutely love IR photography, but this is a rare instance where I don''t think it served the subject well. I find the yellowy background distracts from the beautifully white, well-lit model. She almost disappears into the background since there''s no color or contrast to separate her from it.</td>', 'I absolutely love IR photography, but this is a rare instance where I don''t think it served the subject well. I find the yellowy background distracts from the beautifully white, well-lit model. She almost disappears into the background since there''s no color or contrast to separate her from it.', '2013-02-06 18:41:16.000000', NULL, 1),
(6973705, 1052804, 124982, '<td valign="top">Nicely lit! Wish there was a little more detail in the eye though - the model seems to be squinting in anticipation of the flash?</td>', 'Nicely lit! Wish there was a little more detail in the eye though - the model seems to be squinting in anticipation of the flash?', '2013-02-06 18:42:42.000000', NULL, 1),
(6973710, 1052739, 124982, '<td valign="top">A splendidly lit portrait of your canine friend! Consider me jealous -- would love to take studio-quality images of my animals like this. B&amp;W was a perfect choice!</td>', 'A splendidly lit portrait of your canine friend! Consider me jealous -- would love to take studio-quality images of my animals like this. B&W was a perfect choice!', '2013-02-06 18:44:44.000000', NULL, 1),
(6973711, 1052812, 124982, '<td valign="top">I know i''ve just seen this backdrop in a recent challenge :) lovely model..just a little sharper in the eyes and bingo!</td>', 'I know i''ve just seen this backdrop in a recent challenge :) lovely model..just a little sharper in the eyes and bingo!', '2013-02-06 18:46:24.000000', NULL, 1),
(6973718, 1052735, 124982, '<td valign="top">Very creative -- such a fun image!</td>', 'Very creative -- such a fun image!', '2013-02-06 18:48:03.000000', NULL, 1),
