INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6978451, 1052739, 12611, '<td valign="top">Congrats on the ribbon-well deserved.</td>', 'Congrats on the ribbon-well deserved.', '2013-02-13 09:16:09.000000', NULL, 0),
(6978495, 1052571, 144365, '<td valign="top">I thought this was Monica''s since she''s in the photo. Hence the comment I left. I rather liked the photo because it was different from the rest. Wasn''t the standard fan and a person.<br/> <br/>Now I know why I wasn''t able to get csmithphotography@gmail.com, you took it. Instead I have the shorter christophersmithphotography@gmail.com, no thanks to you.</td>', 'I thought this was Monica''s since she''s in the photo. Hence the comment I left. I rather liked the photo because it was different from the rest. Wasn''t the standard fan and a person. Now I know why I wasn''t able to get csmithphotography@gmail.com, you took it. Instead I have the shorter christophersmithphotography@gmail.com, no thanks to you.', '2013-02-13 10:11:42.000000', NULL, 0),
