(6978596, 1052810, 19825, '<td valign="top">Nice job on a great shot and a top ten finish.</td>', 'Nice job on a great shot and a top ten finish.', '2013-02-13 12:18:51.000000', NULL, 0),
(6978599, 1052811, 19825, '<td valign="top">Beautiful shot -- and so well suited to the challenge. Congrats on the top ten finish.</td>', 'Beautiful shot -- and so well suited to the challenge. Congrats on the top ten finish.', '2013-02-13 12:21:18.000000', NULL, 0),
